/*! notes2 local html_beautify v1 (minimal)
 * Display-only HTML pretty printer used for the HTML textarea view.
 * This is intentionally lightweight (not a full HTML rewriter).
 */
(function (global) {
  'use strict';

  var VOID = {
    area: 1, base: 1, br: 1, col: 1, embed: 1, hr: 1, img: 1, input: 1,
    link: 1, meta: 1, param: 1, source: 1, track: 1, wbr: 1
  };

  function repeat(str, n) {
    var out = '';
    while (n-- > 0) out += str;
    return out;
  }

  function protectBlocks(html, tags) {
    var blocks = [];
    var text = String(html == null ? '' : html);
    if (!tags || !tags.length) return { text: text, blocks: blocks };

    for (var i = 0; i < tags.length; i++) {
      var tag = String(tags[i] || '').toLowerCase();
      if (!tag) continue;
      // Non-greedy match for <tag ...>...</tag> (case-insensitive)
      var re = new RegExp('<' + tag + '\\b[\\s\\S]*?<\\/' + tag + '>', 'gi');
      text = text.replace(re, function (match) {
        var token = '__HTML_BEAUTIFY_BLOCK_' + blocks.length + '__';
        blocks.push(match);
        return token;
      });
    }
    return { text: text, blocks: blocks };
  }

  function restoreBlocks(text, blocks) {
    var out = String(text == null ? '' : text);
    for (var i = 0; i < blocks.length; i++) {
      var token = '__HTML_BEAUTIFY_BLOCK_' + i + '__';
      out = out.split(token).join(blocks[i]);
    }
    return out;
  }

  function isInlineOpenAndCloseSameLine(line) {
    // <tag ...>...</tag> on one line (ignore whitespace-only inner)
    var m = line.match(/^<([a-zA-Z0-9:-]+)(\s[^>]*)?>[\s\S]*<\/\1>\s*$/);
    return !!m;
  }

  function getTagName(line) {
    var m = line.match(/^<\s*([a-zA-Z0-9:-]+)/);
    return m ? m[1].toLowerCase() : '';
  }

  // Expose a global function compatible with js-beautify's name.
  function html_beautify(html, options) {
    var opts = options || {};
    var indentSize = Number(opts.indent_size || 2);
    if (!isFinite(indentSize) || indentSize < 0) indentSize = 2;
    var indentChar = String(opts.indent_char || ' ');
    var indentUnit = repeat(indentChar, indentSize);
    var unformatted = Array.isArray(opts.unformatted) ? opts.unformatted : [];

    var protectedResult = protectBlocks(html, unformatted);
    var text = protectedResult.text
      .replace(/\r\n?/g, '\n')
      .replace(/>\s+</g, '>\n<');

    var lines = text.split('\n');
    var depth = 0;
    var out = [];

    for (var i = 0; i < lines.length; i++) {
      var raw = lines[i];
      var line = raw.trim();
      if (!line) continue;

      // Closing tag decreases depth first
      if (/^<\/[a-zA-Z]/.test(line)) {
        depth = Math.max(depth - 1, 0);
      }

      out.push(repeat(indentUnit, depth) + line);

      // Opening tag increases depth unless it's void/self-closing or inline open+close
      if (
        line[0] === '<' &&
        line[1] !== '/' &&
        line[1] !== '!' &&
        line[1] !== '?' &&
        !/\/>\s*$/.test(line) &&
        !isInlineOpenAndCloseSameLine(line)
      ) {
        var tag = getTagName(line);
        if (tag && !VOID[tag]) depth++;
      }
    }

    return restoreBlocks(out.join('\n'), protectedResult.blocks);
  }

  global.html_beautify = html_beautify;
})(typeof window !== 'undefined' ? window : this);
